import{z as s,x as l,o as n,c as d,q as o,j as i,D as t,d as E,s as B,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"银行挤兑的现代理论","description":"","frontmatter":{"title":"银行挤兑的现代理论","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bm-modern-runs.md","filePath":"econ/bm-modern-runs.md","lastUpdated":1791063341000}'),h={name:"econ/bm-modern-runs.md"};function p(D,a,m,c,C,u){const r=l("Mermaid");return n(),d("div",null,[a[2]||(a[2]=o('<h1 id="银行挤兑的现代理论" tabindex="-1">银行挤兑的现代理论 <a class="header-anchor" href="#银行挤兑的现代理论" aria-label="Permalink to &quot;银行挤兑的现代理论&quot;">​</a></h1><div class="epigraph"><p>挤兑不是群众的非理性，而是一个协调博弈的第二个均衡；现代金融改变的不是这个博弈，而是可跑的债换了几种名字。</p><footer>—— 据 Diamond–Dybvig 1983、Goldstein–Pauzner 2005 整理</footer></div><p><a href="/econ/cf-map">上一课</a>把公司金融深化收在三张清单上，并在边界里把银行的理论——挤兑、监管资本、救助决策——明确交给下一课程。本课开「银行与中介深化」。主干课的 <a href="/econ/diamond-dybvig">Diamond–Dybvig</a> 钉过活期合同与序贯服务，<a href="/econ/shadow-run">影子挤兑</a>钉过 haircut 这套挤兑的价格记法；缺口是把两类现象收成同一个理论对象：<strong>可跑的负债</strong>。什么结构使一项债「可跑」、协调在什么条件下被基本面锁定、均衡怎么删，是本课程后五课共用的地基。之后依次过监管资本、影子银行、最后贷款人与国际银行。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Diamond–Dybvig 给了原型：序贯服务下，同一份活期合同同时支持正常提款与挤兑两个均衡。原型留下三个缺口。其一，多重均衡太「便宜」：模型说挤兑可能，说不了多可能、何时触发。其二，跑的对象早已不限于存款：批发、回购、未保险存款在 2008 与 2023 年轮番出演，大多没有序贯服务条款，为什么同样会跑。其三，政策要动「删掉坏均衡」的旋钮，得先知道哪个旋钮移动协调的边界。</p><p><span class="marginnote">直觉类比：挤兑像影院里有人喊「着火了」——跑不跑不取决于是否真有火，而取决于你猜别人跑不跑；全局博弈给这场猜心加了一点信号噪声，让「火情多真」（基本面多差）决定大家怎么猜。</span></p><h3 id="可跑性的三个合同特征" tabindex="-1">可跑性的三个合同特征 <a class="header-anchor" href="#可跑性的三个合同特征" aria-label="Permalink to &quot;可跑性的三个合同特征&quot;">​</a></h3><p>把可跑的债拆开，共同点是三条：<strong>可随时停止</strong>（活期可提、回购可拒续、票据可不再滚）；<strong>先到先得或续命依赖</strong>（排队者拿残值，或下一笔钱不到今天就无法运营）；<strong>对资产状态不能完全验证</strong>（或验证成本在坏状态下集体爆表）。三条凑齐，持有者的收益表就是协调博弈：预期别人跑，留下就排在队尾，跑是最优反应——与银行资产当下好坏无关。Calomiris–Kahn 1991 还给出这条结构的另一面：跑的权利本身是纪律，存款人事后的惩罚威胁替代了昂贵的持续监督。</p><p><span class="marginnote">2023 年 3 月 SVB：未保险存款占九成上下，单日流出约 420 亿美元、约占存款四分之一。手机银行与社交媒体改变的是协调速度，不是博弈结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>现代理论给原型补两件装置。<strong>全局博弈</strong>（Morris–Shin 1998 的装置，Goldstein–Pauzner 2005 装回活期合同）：把「人人知道人人知道」换成带噪声的信号 \\(x_i=\\theta+\\sigma\\varepsilon_i\\)；噪声足够小时，多重均衡收敛为唯一的阈值规则——基本面 \\(\\theta \\lt \\theta^*\\) 挤兑、\\(\\theta \\gt \\theta^*\\) 不挤，\\(\\theta^*\\) 由保险覆盖、资产风险、排队收益共同决定。多重均衡没有被否认，而是被参数化：挤兑从「可能发生」变成「随参数可比较静态」。<strong>展期风险</strong>（He–Xiong 2012）：把离散提款换成连续滚动的短债，即便资产现金流完全可验证，每期展期失败的可能也使信用利差含一块展期溢价——批发债没有序贯服务条款照样可跑，因为可跑性靠「续命依赖」就够，不靠排队。</p><p><span class="marginnote">术语翻译：「全局博弈」是给「我知道你知道」的无限猜心嵌套加噪声的技术——每人只看到带误差的信号，猜心链条断在噪声处，多重均衡收敛成唯一阈值。「展期风险」是它的连续版：不排队，每期只问一句「下一笔钱还续吗」。</span></p>',12)),(n(),i(A,null,{default:t(()=>[B(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEBT%5B%22%E5%8F%AF%E8%B7%91%E7%9A%84%E5%80%BA%EF%BC%9A%E5%AD%98%E6%AC%BE%E3%80%81%E6%89%B9%E5%8F%91%E3%80%81%E5%9B%9E%E8%B4%AD%E3%80%81%E6%9C%AA%E4%BF%9D%E9%99%A9%E5%AD%98%E6%AC%BE%22%5D%20--%3E%20GAME%5B%22%E5%8D%8F%E8%B0%83%E5%8D%9A%E5%BC%88%EF%BC%9A%E8%B7%91%E8%BF%98%E6%98%AF%E7%95%99%22%5D%0A%20%20GAME%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%20%CE%B8*(%E4%BF%9D%E9%99%A9%E3%80%81%E8%B5%84%E4%BA%A7%E9%A3%8E%E9%99%A9%E3%80%81%E6%8E%92%E9%98%9F%E6%94%B6%E7%9B%8A)%22%5D%0A%20%20TH%20--%3E%7C%22%E4%BD%8E%E4%BA%8E%E9%98%88%E5%80%BC%22%7C%20RUN%5B%22%E6%8C%A4%E5%85%91%E4%B8%8E%E5%81%9C%E6%BB%9A%22%5D%0A%20%20TH%20--%3E%7C%22%E9%AB%98%E4%BA%8E%E9%98%88%E5%80%BC%22%7C%20ROLL%5B%22%E6%AD%A3%E5%B8%B8%E6%BB%9A%E5%8A%A8%E4%B8%8E%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20INS%5B%22%E4%BF%9D%E9%99%A9%E3%80%81%E7%BC%93%E5%BB%BA%E3%80%81%E5%A4%AE%E8%A1%8C%E6%89%BF%E8%AF%BA%22%5D%20--%3E%7C%22%E6%8A%AC%E9%AB%98%E4%B8%8D%E8%B7%91%E7%9A%84%E6%94%B6%E7%9B%8A%22%7C%20TH%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("阈值规则让政策的比较静态有了落点。存款保险把一部分持有者移出「要跑的人」，留下的收益上升，\\(\\theta^*\\) 下移；资产风险上升使坏状态更近，\\(\\theta^*\\) 上移——Goldstein–Pauzner 由此得到「资产风险越高、挤兑概率越高」的可检验含义。缓建与保险删均衡的机理在此统一：都抬高了留下来的收益，把坏均衡移出均衡集，而不是给银行送资本（"),e("a",{href:"/econ/deposit-insurance"},"存款保险"),E(" 的口径）。展期风险解释影子链上「无声的挤兑」：没有恐慌的画面，只有利差与 haircut 的跳升——"),e("a",{href:"/econ/shadow-run"},"影子挤兑"),E("里 Gorton–Metrick 的记法，正是阈值移动的价格表现；而 SVB 的单日四百多亿说明，阈值没变，抵达速度变了。")],-1)),(n(),i(A,null,{default:t(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E5%AD%98%E6%AC%BE%E4%BF%9D%E9%99%A9%E8%A6%86%E7%9B%96%E9%9D%A2%E6%89%A9%E5%A4%A7%22%5D%20--%3E%20L1%5B%22%E7%95%99%E4%B8%8B%E7%9A%84%E6%94%B6%E7%9B%8A%E4%B8%8A%E5%8D%87%22%5D%0A%20%20L1%20--%3E%20DOWN%5B%22%E9%98%88%E5%80%BC%20%CE%B8*%20%E4%B8%8B%E7%A7%BB%EF%BC%9A%E6%8C%A4%E5%85%91%E6%9B%B4%E9%9A%BE%E8%A7%A6%E5%8F%91%22%5D%0A%20%20RISK%5B%22%E8%B5%84%E4%BA%A7%E9%A3%8E%E9%99%A9%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20L2%5B%22%E5%9D%8F%E7%8A%B6%E6%80%81%E6%9B%B4%E8%BF%91%22%5D%0A%20%20L2%20--%3E%20UP%5B%22%E9%98%88%E5%80%BC%20%CE%B8*%20%E4%B8%8A%E7%A7%BB%EF%BC%9A%E6%8C%A4%E5%85%91%E6%9B%B4%E6%98%93%E8%A7%A6%E5%8F%91%22%5D%0A%20%20DOWN%20--%3E%20CMP%5B%22%E6%8C%A4%E5%85%91%E6%A6%82%E7%8E%87%E8%BF%9B%E5%85%A5%E6%AF%94%E8%BE%83%E9%9D%99%E6%80%81%22%5D%0A%20%20UP%20--%3E%20CMP%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲 Diamond–Dybvig 的推导，不写跨行传染——<a href="/econ/bank-contagion">银行间传染</a>的 Allen–Gale 网络是另一个装置，管挤兑怎么沿边传播；本课在单家银行内锁死协调，两者可叠加、不可互替。全局博弈的适用也要交代：它假设信号噪声足够小、行为对他人预期足够敏感，给的是比较静态而非时点预测；当「预测哪一天跑」的工具是用错了地方。监管资本、影子链与救助装置留给后面三课，本课只负责一件事：把可跑的债写成有参数的协调博弈。</p><p><span class="marginnote">常见误区：以为全局博弈能预测「哪一天跑」。它给的是比较静态——参数变了、挤兑概率怎么变，不是时点预测；SVB 单日四百多亿恰好说明阈值没动、速度动了，而速度是技术给的，模型管不了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可跑的债 = 可随时停止 + 先到先得或续命依赖 + 状态不可完全验证；存款、批发、回购同构。</li><li>全局博弈把多重均衡参数化：\\(\\theta \\lt \\theta^*\\) 挤兑，\\(\\theta^*\\) 随保险与资产风险可比较静态。</li><li>展期风险是挤兑的连续版本：不需要序贯服务，每期的续命依赖就够。</li><li>保险与缓建删坏均衡、不加资本；跑的权利本身是纪律（Calomiris–Kahn 1991）。</li><li>协调速度内生于技术：手机与社交网络改速度，不改结构。</li><li>出处：Diamond–Dybvig 1983；Morris–Shin 1998；Goldstein–Pauzner 2005；He–Xiong 2012。</li></ul>',5))])}const b=s(h,[["render",p]]);export{f as __pageData,b as default};
